INSERT INTO `announcements` (`id`, `title`, `category`, `body`, `audience`, `audience_value`, `is_pinned`, `status`, `notify`, `publish_at`, `expires_at`, `attachment`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (1, 'Pembaruan Jam Kerja Selama Ramadan 1447 H', 'KEBIJAKAN', 'Sehubungan dengan bulan suci Ramadan, jam kerja kantor pusat dan cabang disesuaikan mulai pekan depan.
INSERT INTO `announcements` (`id`, `title`, `category`, `body`, `audience`, `audience_value`, `is_pinned`, `status`, `notify`, `publish_at`, `expires_at`, `attachment`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (2, 'Jadwal Payroll & Cut-off Klaim Bulan Ini', 'PAYROLL', 'Berikut jadwal penggajian bulan berjalan agar slip gaji dapat diterima tepat waktu.
INSERT INTO `announcements` (`id`, `title`, `category`, `body`, `audience`, `audience_value`, `is_pinned`, `status`, `notify`, `publish_at`, `expires_at`, `attachment`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (3, 'Pelatihan K3 Wajib untuk Seluruh Karyawan Unit Produksi', 'EVENT', 'Dalam rangka memenuhi standar keselamatan kerja, seluruh karyawan unit produksi wajib mengikuti pelatihan K3.
INSERT INTO `announcements` (`id`, `title`, `category`, `body`, `audience`, `audience_value`, `is_pinned`, `status`, `notify`, `publish_at`, `expires_at`, `attachment`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (4, 'Kebijakan Baru Reimbursement Kesehatan', 'KEBIJAKAN', 'Mulai bulan ini pengajuan reimbursement kesehatan menggunakan alur baru di menu **Klaim Saya**.
